    private static readonly Lazy<Dictionary<string, SimpleIconGlyph>> GlyphBySlugLazy = new(() =>
        Glyphs.ToDictionary(g => g.Slug, StringComparer.OrdinalIgnoreCase));

    private static Dictionary<string, SimpleIconGlyph> GlyphBySlug => GlyphBySlugLazy.Value;

    internal static (Geometry Geometry, Color Color)? GeometryFor(string slug)
    {
        if (!GlyphBySlug.TryGetValue(slug, out var glyph))
            return null;
        try
        {
            // Geometry.Parse returns a frozen StreamGeometry: its properties
            // reject writes, so an artboard remap needs a modifiable clone
            // (setting Transform on the parsed geometry threw
            // InvalidOperationException and took the whole icon catalog down
            // on the first non-24x24 viewBox glyph).
            var geometry = Geometry.Parse(glyph.Path);
            if (glyph.ViewW != 24 || glyph.ViewH != 24 ||
                glyph.ViewX != 0 || glyph.ViewY != 0)
            {
                var scaleX = 24.0 / glyph.ViewW;
                var scaleY = 24.0 / glyph.ViewH;
                geometry = geometry.Clone();
                geometry.Transform = new MatrixTransform(scaleX, 0, 0, scaleY,
                    -glyph.ViewX * scaleX, -glyph.ViewY * scaleY);
            }
            geometry.Freeze();
            return (geometry, ParseColor(glyph.Hex));
        }
        catch (FormatException)
        {
            return null;
        }
    }

    private static Color ParseColor(string hex)
    {
        var value = uint.Parse(hex.TrimStart('#'), System.Globalization.NumberStyles.HexNumber);
        var r = (byte)(value >> 16);
        var g = (byte)(value >> 8);
        var b = (byte)value;
        // Near-black brand colors (rust, bun, github) vanish on the dark tab
        // strip; lift them to a readable gray.
        var luminance = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255.0;
        if (luminance < 0.25)
            return Color.FromRgb(0xB8, 0xB8, 0xBE);
        return Color.FromRgb(r, g, b);
    }
}
